    # Chapter headings: <h2 class="chapter-title">Chapter One: The Shock</h2>
    for m in re.finditer(
        r'<(h[12]\s+class="[^"]*chapter-title[^"]*")>(Chapter\s+\w+:\s+.*?)</(h[12])>',
        html, re.IGNORECASE,
    ):
